param([string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$BuildRoot='')
. (Join-Path $PSScriptRoot 'ProjectedRequest.ps1')
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot out/release};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot)
Add-Type -Path (Join-Path $PSScriptRoot PrivateDesktop.cs)
$root=Join-Path $ProjectRoot ('artifacts/desk-drops-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null
$env:HIBERNATION_SESSION_KEY='desk-drops-session';$env:HIBERNATION_DROP_KEY='synthetic-drop-key';$env:TEMP=Join-Path $root tmp;$env:TMP=$env:TEMP;New-Item -ItemType Directory -Force $env:TEMP|Out-Null
$provider=$null;$desktop=$null;$service=$null;$checks=0
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name,[int]$Seconds=30){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 30};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$p=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer desk-drops-session'};TimeoutSec=10};if($null-ne$Data){$p.Method='Post';$p.ContentType='application/json';$p.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 50 -Compress))};Invoke-RestMethod @p}
function Plan($Items){@{nonce=[Guid]::NewGuid().ToString('N');responses=@($Items|ForEach-Object {@{response=$_}})}|ConvertTo-Json -Depth 50|Set-Content (Join-Path $root provider/plan.json) -Encoding utf8}
function Calls($Name,$Arguments){@{version=1;kind='call';text=$null;calls=@(@{id='fixture';tool=$Name;args=$Arguments})}}
function Reply{@{version=1;kind='reply';text='留下一点甜味。';calls=@();presentation=@{speech=$false;bubble=$false}}}
function Message($Text){$null=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text=$Text};Wait-For {!(Api '/api/chat').busy} 'turn'}
function Feedback{$capture=Get-Content (Join-Path $root provider/last-request.json) -Raw|ConvertFrom-Json -Depth 60;@(($capture.messages[-1].content|ConvertFrom-Json -Depth 50).tool_results)[0]}
function World{(Api '/api/capabilities').plugins.Where({$_.id-eq'habitat'})[0].current}
function Plugin($Name,$Arguments){$null=Api '/api/plugin/test' @{tool=$Name;args=$Arguments};Wait-For {$script:receipt=Api '/api/plugin/result';$script:receipt.state-in@('succeeded','failed')} $Name;return $script:receipt.result}
function Start-Backend{Remove-Item (Join-Path $root ready.json) -ErrorAction SilentlyContinue;$script:desktop=[PrivateDesktop]::new((Join-Path $BuildRoot hibernation-agent.exe),(Join-Path $root config.json),(Join-Path $root ready.json),$ProjectRoot);$script:service=$desktop.Child;Wait-For {if($service.HasExited){throw 'fixture exited'};Test-Path (Join-Path $root ready.json)} 'ready';$script:origin='http://127.0.0.1:'+((Get-Content (Join-Path $root ready.json) -Raw|ConvertFrom-Json).port)}
function Stop-Backend{$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'graceful shutdown';$desktop.Dispose();$script:desktop=$null}
function Alpha{$capture=$desktop.CaptureClient($desktop.Find('HibernationDeskObjects'));$max=0;for($i=3;$i-lt$capture.Bgra.Length;$i+=4){$max=[Math]::Max($max,$capture.Bgra[$i])};return $max}
try{
 $provider=Start-Process (Join-Path $BuildRoot Hibernation_TestProvider.exe) -ArgumentList ('"'+$root+'/provider"') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root provider.log) -RedirectStandardError (Join-Path $root provider-error.log);Wait-For {Test-Path (Join-Path $root provider/port)} 'provider';$fixture='http://127.0.0.1:'+(Get-Content (Join-Path $root provider/port))
 $cfg=Get-Content (Join-Path $ProjectRoot config/example.json) -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot=Join-Path $root data;$cfg.characterRoot=Join-Path $ProjectRoot character;$cfg.uiRoot=Join-Path $ProjectRoot ui;$cfg.pluginRoot=Join-Path $BuildRoot plugins;$cfg.frontend.startupAnimation=$false;$cfg.solitudeIntervalMs=600000;$cfg.idleBeforeSolitudeMs=600000;$cfg.maxStartsPerHour=1000;$cfg.review=@{enabled=$false};$cfg.plugins=@{widget=@{enabled=$true;roam=$false;autonomousMode=$true;autonomyIdleSeconds=600};habitat=@{enabled=$true;autoSpawn=$false;autoInteract=$false;maxObjects=3;lifetimeMinSeconds=5;lifetimeMaxSeconds=60;creationsPerMinute=12;reducedMotion=$true}}
 $cfg.profiles+=@{id='actor';label='Drop fixture';enabled=$true;protocol='chat-completions';origin=$fixture;basePath='/v1';model='fixture-model';credentialEnvironment='HIBERNATION_DROP_KEY';timeoutMs=15000;maxOutputTokens=2048};$cfg|ConvertTo-Json -Depth 50|Set-Content (Join-Path $root config.json) -Encoding utf8
 Start-Backend;$null=Api '/api/model' @{id='actor'};Wait-For {(World).desktop} 'world ready';Check (@((Api '/api/capabilities').tools|Where-Object tool -eq habitat.create).Count-eq1) 'model discovers creation tool without hints'
 $definition=@{name='月光布丁';description='晃起来像一小块月光。';tint='sky';tags=@('甜点','柔软');traits=@(@{key='甜度';value=3},@{key='发光';value=$true})}
 Plan @((Calls 'habitat.create' @{kind='pudding';definition=$definition;lifetime_min_seconds=60;lifetime_max_seconds=60}),(Reply));Message '创造一份虚拟甜点';$feedback=Feedback;$food=$feedback.result.object
 Check ($feedback.ok-and$food.definition.name-eq'月光布丁'-and$food.definition.traits.Count-eq2) 'model authored name and scalar traits reach actual world'
 Check ($food.rules.edible-and$food.rules.nutrition-ge20-and$food.rules.nutrition-le24-and$food.creator-eq'model'-and[math]::Abs($food.expires-$food.born-60)-lt.001) 'program assigns bounded food effects rarity and exact lifetime'
 $bad=Plugin 'habitat.create' @{kind='apple';definition=@{name='伪造';nutrition=999}};Check (!$bad.ok-and(World).objects.Count-eq1) 'unknown authoritative field rejected without partial spawn'
 $bad=Plugin 'habitat.create' @{kind='apple';definition=@{traits=@(@{key='nutrition';value=999})}};Check (!$bad.ok-and$bad.error.code-eq'world_definition_invalid') 'reserved trait cannot masquerade as a numeric rule'
 $bad=Plugin 'habitat.create' @{kind='apple';lifetime_min_seconds=20;lifetime_max_seconds=10};Check (!$bad.ok-and$bad.error.code-eq'world_lifetime_policy') 'inverted duration interval rejected'
 $bad=Plugin 'habitat.create' @{kind='apple';lifetime_max_seconds=61};Check (!$bad.ok-and(World).objects.Count-eq1) 'model cannot extend user configured duration ceiling'
 Plan @((Calls 'activity.enqueue' @{commands=@(@{kind='eat_nearest';seconds=0})}),(Reply));Message '让它自行走到甜点旁边';Wait-For {(World).objects.Count-eq0} 'new food reached and eaten' 30
 $ate=World;Check ($ate.last_actions[-1].kind-eq'habitat.consumed'-and$ate.last_actions[-1].item.definition.name-eq'月光布丁') 'cached autonomous eat recognizes new templates and records actual named result'
 Wait-For {(World).retiring_count-eq0} 'consumption ghost retires';Check ((World).last_actions.Count-eq1) 'retiring visual never causes a duplicate eating result'
 Plan @((Calls 'habitat.observe' @{}),(Reply));Message '刚才发生的事';$capture=Get-Content (Join-Path $root provider/last-request.json) -Raw|ConvertFrom-Json -Depth 60;$context=Model-CurrentEvent $capture;Check (@($context.authorized_context|Where-Object {$_.data.text-like'*月光布丁*'-and$_.data.plugin_event_id}).Count-ge1) 'later conversation receives named completed experience with actual source'
 $created=Plugin 'habitat.create' @{kind='crystal';definition=@{name='短暂的星石'};lifetime_min_seconds=8;lifetime_max_seconds=8};$drop=$created.result.object;Wait-For {$a=Alpha;$a-gt0-and$a-lt255} 'native per item fade in' 3;Check ((World).alpha_rendering-and(Alpha)-lt255) 'native bitmap begins with real fractional alpha'
 Wait-For {(Alpha)-eq255} 'fully appeared';$w=World;Check ($w.surface_width-lt200-and$w.surface_height-lt200) 'single drop updates only a bounded transparent surface'
 $null=Api '/api/control' @{paused=$true};$frozen=World;$pixels=Alpha;Start-Sleep -Milliseconds 500;Check ((World).clock-eq$frozen.clock-and(Alpha)-eq$pixels) 'pause freezes lifetime and alpha together';$null=Api '/api/control' @{paused=$false}
 Wait-For {$w=World;$w.objects.Count-eq1-and$w.clock-gt($drop.expires-1)-and$w.clock-lt$drop.expires} 'last fade interval' 12;Check ((Alpha)-gt0-and(Alpha)-lt255-and(World).objects.Count-eq1) 'native fade out precedes actual expiry'
 Wait-For {(World).objects.Count-eq0} 'expired';Check ((Alpha)-eq0-and(World).retiring_count-eq0) 'expiry removes transparent object without a leftover ghost'
 $savedDrop=(Plugin 'habitat.create' @{kind='apple';definition=@{name='晚一点的苹果'};lifetime_min_seconds=20;lifetime_max_seconds=40}).result.object;Check (($savedDrop.expires-$savedDrop.born)-ge20-and($savedDrop.expires-$savedDrop.born)-le40) 'actual lifetime sampled inside requested interval'
 $null=Api '/api/control' @{paused=$true};$saved=(World).objects|ConvertTo-Json -Depth 40 -Compress;Stop-Backend;Start-Backend;Check (((World).objects|ConvertTo-Json -Depth 40 -Compress)-eq$saved-and(World).version-eq2) 'restart preserves definitions rules and sampled expiry'
 $null=Api '/api/control' @{paused=$false};$null=Plugin 'habitat.create' @{kind='bread'};$null=Plugin 'habitat.create' @{kind='tea'};$full=Plugin 'habitat.create' @{kind='berry'};Check (!$full.ok-and$full.error.code-eq'world_object_limit'-and(World).objects.Count-eq3) 'capacity prevents unlimited model creation'
 $observed=Plugin 'habitat.observe' @{};Check ($observed.result.creation_policy.templates-contains'crystal'-and$observed.result.creation_policy.lifetime_min_seconds-eq5) 'observation supplies templates and enforceable creation policy'
 $settings=(Api '/api/dashboard').settings|ConvertTo-Json -Depth 50|ConvertFrom-Json -AsHashtable;$settings.plugins.habitat.maxObjects=8;$settings.plugins.habitat.creationsPerMinute=1;$null=Api '/api/settings' @{settings=$settings};$null=Plugin 'habitat.create' @{kind='paper_star'};$limited=Plugin 'habitat.create' @{kind='paper_star'};Check (!$limited.ok-and$limited.error.code-eq'world_creation_rate') 'per minute creation limit works independently of capacity'
 $settings.plugins.habitat.lifetimeMinSeconds=61;$rejected=$false;try{$null=Api '/api/settings' @{settings=$settings}}catch{$rejected=$true};Check ($rejected-and(World).creation_policy.lifetime_min_seconds-eq5) 'invalid configured lifetime range leaves working plugin in place'
 Check ((Api '/api/chat').health-eq'ok') 'application stays healthy';Stop-Backend
 @{completed=$true;checks=$checks;root=$root;endedUtc=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content (Join-Path $root acceptance.json);Write-Output "Desk drops passed: $checks checks. $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited-and$service.Path-eq(Join-Path $BuildRoot hibernation-agent.exe)){Stop-Process -Id $service.Id}}};if($desktop){$desktop.Dispose()};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
